-- Comprehensive 2026 comparison model catalog, reconciled against the deep-research verification pack.
-- Keeps model identity/access/spec snapshots on `models` and stores benchmark conditions in a normalized child table.

ALTER TABLE models ADD COLUMN IF NOT EXISTS family TEXT;
ALTER TABLE models ADD COLUMN IF NOT EXISTS ga_date DATE;
ALTER TABLE models ADD COLUMN IF NOT EXISTS metadata JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS model_benchmarks (
  id TEXT PRIMARY KEY,
  model_slug TEXT NOT NULL REFERENCES models(slug) ON DELETE CASCADE,
  category TEXT NOT NULL CHECK (category IN ('coding', 'math_reasoning', 'knowledge', 'agentic_computer_use', 'multimodal', 'professional', 'other')),
  benchmark_name TEXT NOT NULL,
  benchmark_version TEXT,
  score_numeric DOUBLE PRECISION,
  score_display TEXT NOT NULL,
  score_unit TEXT,
  tools BOOLEAN,
  reasoning_effort TEXT,
  harness TEXT,
  evaluator TEXT,
  evaluation_date DATE,
  source TEXT,
  notes TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS model_benchmarks_model_idx ON model_benchmarks (model_slug, category, benchmark_name);
CREATE INDEX IF NOT EXISTS models_family_idx ON models (family, release_date DESC);

-- ERNIE 5.0 was already public in 2025; it should not appear in the 2026 launch catalog.
DELETE FROM models WHERE slug = 'ernie-5-0';

INSERT INTO models (
  slug, name, developer, release_date, ga_date, access, family,
  comparison_data, sources, notes, metadata, verified_at
)
SELECT
  seed.slug,
  seed.name,
  seed.developer,
  seed.release_date::date,
  NULLIF(seed.ga_date, '')::date,
  seed.access,
  seed.family,
  seed.comparison_data,
  seed.sources,
  seed.notes,
  COALESCE(seed.metadata, '{}'::jsonb),
  NOW()
FROM jsonb_to_recordset($newmodels$
