$newmodels$::jsonb) AS seed(
  slug text,
  name text,
  developer text,
  release_date text,
  ga_date text,
  access text,
  family text,
  comparison_data jsonb,
  sources jsonb,
  notes text,
  metadata jsonb
)
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  developer = EXCLUDED.developer,
  release_date = EXCLUDED.release_date,
  ga_date = EXCLUDED.ga_date,
  access = EXCLUDED.access,
  family = EXCLUDED.family,
  comparison_data = EXCLUDED.comparison_data,
  sources = EXCLUDED.sources,
  notes = EXCLUDED.notes,
  metadata = EXCLUDED.metadata,
  verified_at = NOW(),
  updated_at = NOW();

UPDATE models AS model
SET
  name = COALESCE(patch.name, model.name),
  release_date = COALESCE(NULLIF(patch.release_date, '')::date, model.release_date),
  ga_date = COALESCE(NULLIF(patch.ga_date, '')::date, model.ga_date),
  access = COALESCE(patch.access, model.access),
  family = COALESCE(patch.family, model.family),
  comparison_data = COALESCE(model.comparison_data, '{}'::jsonb) || COALESCE(patch.comparison_data, '{}'::jsonb),
  sources = (
    SELECT COALESCE(jsonb_agg(dedup.value ORDER BY dedup.ordinality), '[]'::jsonb)
    FROM (
      SELECT DISTINCT ON (entry.value->>'url') entry.value, entry.ordinality
      FROM jsonb_array_elements(
        COALESCE(model.sources, '[]'::jsonb) || COALESCE(patch.sources, '[]'::jsonb)
      ) WITH ORDINALITY AS entry(value, ordinality)
      WHERE COALESCE(entry.value->>'url', '') <> ''
      ORDER BY entry.value->>'url', entry.ordinality DESC
    ) AS dedup
  ),
  notes = COALESCE(patch.notes, model.notes),
  metadata = COALESCE(model.metadata, '{}'::jsonb) || COALESCE(patch.metadata, '{}'::jsonb),
  verified_at = NOW(),
  updated_at = NOW()
FROM jsonb_to_recordset($patches$
