$patches$::jsonb) AS patch(
  slug text,
  name text,
  release_date text,
  ga_date text,
  access text,
  family text,
  comparison_data jsonb,
  sources jsonb,
  notes text,
  metadata jsonb
)
WHERE model.slug = patch.slug;

-- Defensive family labels for any future/older model not explicitly covered above.
UPDATE models
SET
  family = CASE
    WHEN name ILIKE 'GPT-6%' THEN 'GPT-6'
    WHEN name ILIKE 'GPT-5.6%' THEN 'GPT-5.6'
    WHEN name ILIKE 'GPT-5.5%' THEN 'GPT-5.5'
    WHEN name ILIKE 'GPT-5.4%' THEN 'GPT-5.4'
    WHEN name ILIKE 'GPT-5.3%' THEN 'GPT-5.3'
    WHEN name ILIKE 'Claude%' THEN 'Claude'
    WHEN name ILIKE 'Gemini Omni%' THEN 'Gemini Omni'
    WHEN name ILIKE 'Gemini 3.8%' THEN 'Gemini 3.8'
    WHEN name ILIKE 'Gemini 3.7%' THEN 'Gemini 3.7'
    WHEN name ILIKE 'Gemini 3.6%' THEN 'Gemini 3.6'
    WHEN name ILIKE 'Gemini 3.5%' THEN 'Gemini 3.5'
    WHEN name ILIKE 'Gemini 3.1%' THEN 'Gemini 3.1'
    WHEN name ILIKE 'Gemma 4%' THEN 'Gemma 4'
    WHEN name ILIKE 'Muse%' THEN 'Muse'
    WHEN name ILIKE 'Grok 4%' THEN 'Grok 4'
    WHEN name ILIKE 'Kimi K2%' THEN 'Kimi K2'
    WHEN name ILIKE 'Kimi K3%' THEN 'Kimi K3'
    WHEN name ILIKE 'Qwen3.8%' THEN 'Qwen3.8'
    WHEN name ILIKE 'Qwen3.7%' THEN 'Qwen3.7'
    WHEN name ILIKE 'Qwen3.6%' THEN 'Qwen3.6'
    WHEN name ILIKE 'Qwen3.5%' THEN 'Qwen3.5'
    WHEN name ILIKE 'DeepSeek V4%' THEN 'DeepSeek V4'
    WHEN name ILIKE 'Mistral Small 4%' THEN 'Mistral Small 4'
    WHEN name ILIKE 'Mistral Medium 3.5%' THEN 'Mistral Medium 3.5'
    WHEN name ILIKE 'Command A+%' THEN 'Command A'
    WHEN name ILIKE 'Jamba2%' THEN 'Jamba2'
    WHEN name ILIKE 'MiniMax M3%' THEN 'MiniMax M3'
    WHEN name ILIKE 'MiniMax M2%' THEN 'MiniMax M2'
    WHEN name ILIKE 'GLM-5V%' THEN 'GLM-5V'
    WHEN name ILIKE 'GLM-5%' THEN 'GLM-5'
    WHEN name ILIKE 'GLM-4.7%' THEN 'GLM-4.7'
    WHEN name ILIKE 'ERNIE 5%' THEN 'ERNIE 5'
    ELSE developer
  END,
  updated_at = NOW()
WHERE family IS NULL OR trim(family) = '';

INSERT INTO model_benchmarks (
  id, model_slug, category, benchmark_name, benchmark_version,
  score_numeric, score_display, score_unit, tools, reasoning_effort,
  harness, evaluator, evaluation_date, source, notes
)
SELECT
  evidence.id,
  evidence.model_slug,
  evidence.category,
  evidence.benchmark_name,
  evidence.benchmark_version,
  evidence.score_numeric,
  evidence.score_display,
  evidence.score_unit,
  evidence.tools,
  evidence.reasoning_effort,
  evidence.harness,
  evidence.evaluator,
  NULLIF(evidence.evaluation_date, '')::date,
  evidence.source,
  evidence.notes
FROM jsonb_to_recordset($benchmarks$
